package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.time.Instant;
import java.util.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Exact original LeafCutter workflows with native scientific audits and atomic whole-batch admission. */
public final class LeafCutterWorkflowCli {
    private LeafCutterWorkflowCli() { }
    static final String ACTION="Require exit0 AND analysis-status.json result_admitted=true. Read WARNINGS.md, source-identifier-mapping.json, sample-selection.json, original binary fits, source reports, all original stdout/stderr and process receipts. FAIL2 admits no result from the whole requested batch, including earlier completed stages/cases. Preserve all originals/provisionals and correct the named input, model, precision, runtime, timeout or capacity cause before retrying NEW paths. SKIP3 skips dependent analysis: provide the exact permitted Linux/WSL runtime using separate CAPTURE/INSTALL preparation; installation needs explicit permission flags. Where installation is forbidden, keep analysis skipped. RUN installs nothing and never substitutes an edition, repairs IDs/counts, hides missing states or infers paper thresholds. Native checks evaluate retained estimates; they do not independently refit/authenticate a model, certify global optima, biological calibration or historical paper reproduction.";
    record Captured(Path source,Path copy,NextflowFiles.Pin pin) { }
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    public static int run(String[] args,PrintStream output,PrintStream error){
        if(args.length==1&&args[0].equals("--help")){output.println("java -cp DEVELOPMENT.jar org.jlinalg.cli.LeafCutterWorkflowCli --request request.json\nExplicit cluster, phenotype, differential or complete pipeline cases. Original source2c9907ef66ad/R package0.2.9; Linux x86_64 runtime execution, portable native Java APIs. Declare every scientific threshold, RNG seed, literal chromosome blacklist and groups-file-order policy. RegTools BED12 is supplied input; BAM junction extraction, downstream QTL engines, bgzip/tabix and LeafViz are separate tools.\n"+ACTION);return 0;}
        Path out=null;int exit=2;var warnings=new ArrayList<String>();warnings.add(ACTION);var state=new LinkedHashMap<String,Object>();state.put("status","RUNNING_NO_RESULT_ADMITTED");state.put("result_admitted",false);state.put("started_at",Instant.now().toString());state.put("required_action",ACTION);
        try{
            require(args.length==2&&args[0].equals("--request"),"Use --request FILE or --help");Path requestPath=Path.of(args[1]).toAbsolutePath().normalize();byte[] raw=NextflowFiles.bytes(requestPath,16777216);var requestPin=new NextflowFiles.Pin(raw.length,NextflowFiles.sha(raw));require(requestPin.equals(NextflowFiles.pin(requestPath,16777216,()->{})),"Original request changed during capture");var request=LeafCutterWorkflowRequest.parse(object(NextflowParameters.parse(NextflowFiles.utf8(raw),16777216,2000000)),requestPath.getParent());Path wanted=request.out();require(!Files.exists(wanted,LinkOption.NOFOLLOW_LINKS)&&canonicalMissing(wanted).equals(wanted),"Require NEW output under canonical unlinked parents");require(!requestPath.startsWith(wanted)&&!request.runtime().startsWith(wanted),"Output overlaps original request/runtime manifest");for(var input:request.inputs())require(!wanted.startsWith(input.source())&&!input.source().startsWith(wanted),"Output overlaps an original input");
            if(Files.isRegularFile(request.runtime(),LinkOption.NOFOLLOW_LINKS)){var quick=LeafCutterWorkflowRuntime.read(request.runtime(),67108864);for(String key:List.of("runtime_environment","R_library"))if(quick.get(key) instanceof String s){Path root=canonicalMissing(Path.of(s).toAbsolutePath().normalize());require(!wanted.startsWith(root)&&!root.startsWith(wanted),"Output overlaps a read-only original runtime/library tree");}}
            Files.createDirectories(wanted.getParent());Files.createDirectory(wanted);out=wanted;Files.write(out.resolve("request.original.json"),raw,StandardOpenOption.CREATE_NEW);status(out,state);error.println("LeafCutter: verifying exact original dependencies; the whole batch remains unadmitted.");var runtime=LeafCutterWorkflowRuntime.prepare(request);require(!out.startsWith(runtime.prefix())&&!runtime.prefix().startsWith(out)&&!out.startsWith(runtime.library())&&!runtime.library().startsWith(out),"Output overlaps original runtime/library");Path inputHome=Files.createDirectory(out.resolve("inputs"));var captured=new ArrayList<Captured>();var paths=new LinkedHashMap<String,Path>();var captureRecords=new ArrayList<Object>();long bytes=0;int files=0;
            for(var input:request.inputs()){
                require(++files<=request.maximumFiles(),"Complete input member capacity exceeded");Path copy=inputHome.resolve(input.id()+".original");var pin=NextflowFiles.pin(input.source(),request.inputBytes()-bytes,()->{});Files.copy(input.source(),copy);require(pin.equals(NextflowFiles.pin(copy,request.inputBytes()-bytes,()->{}))&&pin.equals(NextflowFiles.pin(input.source(),request.inputBytes()-bytes,()->{})),"Original/captured input changed during complete byte copy");bytes=Math.addExact(bytes,pin.bytes());captured.add(new Captured(input.source(),copy,pin));paths.put(input.id(),copy);captureRecords.add(Map.of("id",input.id(),"source",input.source().toString(),"captured",copy.toString(),"bytes",pin.bytes(),"sha256",pin.sha256()));
            }
            NextflowFiles.writeJson(out.resolve("input-capture.json"),captureRecords);preflight(request,paths);LeafCutterWorkflowRuntime.sources(out.resolve("source"));var effective=request.worker(paths);NextflowFiles.writeJson(out.resolve("effective-request.json"),effective);error.println("LeafCutter: executing every explicit original program stage.");var report=LeafCutterWorkflowRuntime.execute(out.resolve("worker"),request,runtime,effective);var meter=new LeafCutterWorkflowAudit.Meter(request.auditOperations());var audits=new ArrayList<Object>();var cases=list(report.get("cases"));require(cases.size()==request.analyses().size(),"Original case family incomplete");
            for(int i=0;i<cases.size();i++){
                var result=object(cases.get(i));var c=request.analyses().get(i);require(text(result.get("id")).equals(text(c.get("id")))&&text(result.get("kind")).equals(text(c.get("kind"))),"Original cases reordered or changed kind");Path home=out.resolve("worker").resolve(text(c.get("id")));audits.add(LeafCutterWorkflowAudit.analyze(c,home,paths,request,warnings,meter));diagnostics(home,warnings,request);
            }
            NextflowFiles.writeJson(out.resolve("native-audit.json"),Map.of("cases",audits,"audit_operations",meter.used,"independent_optimizer_refitting",false));error.println("LeafCutter: rechecking all original inputs, source members and complete runtime trees before admission.");runtime.verify();LeafCutterWorkflowRuntime.verifySources(out.resolve("source"));for(var input:captured)require(input.pin().equals(NextflowFiles.pin(input.source(),request.inputBytes(),()->{}))&&input.pin().equals(NextflowFiles.pin(input.copy(),request.inputBytes(),()->{})),"Original/captured input changed during analysis");require(requestPin.equals(NextflowFiles.pin(requestPath,16777216,()->{})),"Original request changed during analysis");state.put("status","PASS_ORIGINAL_LEAFCUTTER_WORKFLOWS");state.put("edition",request.edition());state.put("cases",audits);state.put("paper_reproduced",false);state.put("atomic_batch",true);state.put("finished_at",Instant.now().toString());warnings(out,state,warnings);var manifest=manifest(out,request);NextflowFiles.writeJson(out.resolve("manifest.json"),manifest);state.put("manifest_sha256",NextflowFiles.pin(out.resolve("manifest.json"),67108864,()->{}).sha256());state.put("result_admitted",true);status(out,state);exit=0;output.println("LeafCutter complete batch admitted: "+out+"\nRead WARNINGS.md and analysis-status.json before using results.");
        }catch(LeafCutterWorkflowRuntime.Unavailable failure){exit=3;state.put("status","SKIP3_LEAFCUTTER_DEPENDENCIES_UNAVAILABLE");state.put("error",failure.toString());warnings.add(failure.toString());error.println("LEAFCUTTER SKIP3: "+failure+"\nREQUIRED ACTION: "+ACTION);}
        catch(Exception failure){state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("error",failure.toString());warnings.add(failure.toString());error.println("LEAFCUTTER FAIL2: "+failure+"\nREQUIRED ACTION: "+ACTION);}
        catch(OutOfMemoryError failure){state.put("status","FAIL2_JAVA_HEAP_EXHAUSTED");state.put("error",failure.toString());warnings.add("Java heap exhausted; no partial native audit or original batch is admitted.");error.println("LEAFCUTTER FAIL2: Java heap exhausted. "+ACTION);}
        finally{if(exit!=0&&out!=null){state.put("result_admitted",false);state.put("finished_at",Instant.now().toString());try{warnings(out,state,warnings);status(out,state);}catch(IOException failure){error.println("LEAFCUTTER FAIL2: failure receipt could not be finalized: "+failure+". Preserve the whole unadmitted directory.");exit=2;}}if(out!=null)error.println("WARNINGS / REQUIRED ACTIONS: "+out.resolve("WARNINGS.md"));}return exit;
    }
    private static void preflight(LeafCutterWorkflowRequest.Request request,Map<String,Path> captured)throws IOException {
        for(var c:request.analyses()){String id=text(c.get("id")),kind=text(c.get("kind"));if(kind.equals("cluster")||kind.equals("pipeline"))LeafCutterWorkflowInputs.junctions(c,captured,request.inputBytes());if(kind.equals("phenotype"))LeafCutterWorkflowInputs.matrix(captured.get(id+"-counts_ratio"),true,request.inputBytes());if(kind.equals("differential")){var counts=LeafCutterWorkflowInputs.matrix(captured.get(id+"-counts"),false,request.inputBytes());LeafCutterWorkflowInputs.groups(captured.get(id+"-groups"),counts,request.inputBytes());}}
    }
    private static void diagnostics(Path home,List<String> warnings,LeafCutterWorkflowRequest.Request request)throws IOException {
        Path ds=home.resolve("differential");if(Files.isDirectory(ds)){try(var paths=Files.list(ds)){for(Path path:paths.toList())if(path.getFileName().toString().startsWith("condition-")&&path.getFileName().toString().endsWith(".json")){var condition=LeafCutterWorkflowRuntime.read(path,1048576);warnings.add("ORIGINAL R "+text(condition.get("type")).toUpperCase(Locale.ROOT)+" ["+home.getFileName()+"]: "+text(condition.get("message")));}}}
        try(var paths=Files.list(home)){for(Path path:paths.toList())if(path.getFileName().toString().endsWith(".stderr")&&Files.size(path)>0)warnings.add("Original diagnostics retained verbatim: "+path+". Read this file even when the batch passed.");}
    }
    private static Map<String,Object> manifest(Path root,LeafCutterWorkflowRequest.Request request)throws IOException {
        var files=new TreeMap<String,Object>();var directories=new TreeSet<String>();long[] bytes={0};int[] count={0};Files.walkFileTree(root,new SimpleFileVisitor<>(){
            private void capacity(long size)throws IOException{require(++count[0]<=request.maximumFiles()&&size<=request.outputBytes()-bytes[0],"Complete output capacity exceeded; no partial family is admitted");bytes[0]+=size;}
            @Override public FileVisitResult preVisitDirectory(Path path,BasicFileAttributes attrs)throws IOException{if(!path.equals(root)){capacity(0);directories.add(root.relativize(path).toString().replace('\\','/'));}return FileVisitResult.CONTINUE;}
            @Override public FileVisitResult visitFile(Path path,BasicFileAttributes attrs)throws IOException{String name=root.relativize(path).toString().replace('\\','/');if(name.equals("analysis-status.json")||name.equals("manifest.json"))return FileVisitResult.CONTINUE;require(attrs.isRegularFile()&&!attrs.isSymbolicLink(),"Linked/nonregular original output is outside this workflow profile");capacity(attrs.size());files.put(name,LeafCutterWorkflowRuntime.pinObject(NextflowFiles.pin(path,request.outputBytes(),()->{})));return FileVisitResult.CONTINUE;}
        });return Map.of("schema_version",1,"directories",directories,"files",files,"captured_bytes",bytes[0],"result_admission","Require analysis-status.json result_admitted=true; raw original files, typed snapshots and RDS fits remain retained.");
    }
    private static Path canonicalMissing(Path path)throws IOException{var suffix=new ArrayDeque<Path>();Path current=path;while(!Files.exists(current,LinkOption.NOFOLLOW_LINKS)){require(current.getParent()!=null,"Missing canonical output ancestor");suffix.addFirst(current.getFileName());current=current.getParent();}current=current.toRealPath();for(Path part:suffix)current=current.resolve(part);return current;}
    private static void status(Path out,Map<String,Object> state)throws IOException{Path temporary=out.resolve(".analysis-status-"+UUID.randomUUID()+".tmp");Files.writeString(temporary,NextflowJson.json(state)+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);Files.move(temporary,out.resolve("analysis-status.json"),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
    private static void warnings(Path out,Map<String,Object> state,List<String> messages)throws IOException{Files.writeString(out.resolve("WARNINGS.md"),"# "+state.get("status")+"\n\n"+String.join("\n\n",messages)+"\n\nRequired action: "+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);}
}
